import fitz
from pathlib import Path
keywords = ["arXiv", "arxiv", "Correspondence", "Affiliation", "University", "Institute", "Department", "Accepted", "Proceedings", "Interspeech", "ICASSP", "ICML", "ACL", "NeurIPS", "AAAI", "CVPR", "EMNLP", "COLING", "NAACL", "EACL", "SIG", "IEEE", "ACM", "Preprint", "Acknowledg", "funding", "grant", "ORCID", "email", "@", "Duke", "Carnegie", "Cornell", "Georgia", "Renmin", "Adobe", "San Jose", "Durham", "USA"]

for i in range(1,4):
    path = Path(f"/root/paper{i}.pdf")
    doc = fitz.open(path)
    print('\n===', path.name, '===')
    for pno in range(doc.page_count):
        text = doc[pno].get_text()
        low = text.lower()
        hit = False
        for kw in keywords:
            if kw.lower() in low:
                hit = True
                break
        if hit:
            print('page', pno+1)
            # print lines containing keywords
            for line in text.splitlines():
                l = line.lower()
                if any(kw.lower() in l for kw in keywords):
                    print('  ', line)
    doc.close()
PY"}

